using System;
using System.Collections.Generic;

namespace XingShuRuntime.UI
{
    /// <summary>
    /// XingShu 生产级原子 UI 资产确定性编译内嵌载荷表 (Self-Contained Payload Contract)
    /// 规避 Unity IL2CPP / HybridCLR 对动态程序集 GetManifestResourceStream 的反射截断限制，
    /// 确保在任何引擎平台、任何加载器环境下核心原子视觉切片 100% 必定命中。
    /// </summary>
    internal static class XingShuUIAssetPayloads
    {
        private static readonly Dictionary<string, byte[]> _payloads = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);

        static XingShuUIAssetPayloads()
        {
            RegisterPayload("button_primary.png", "XingShu.button_primary.png", "");
            RegisterPayload("button_secondary.png", "XingShu.button_secondary.png", "");
            RegisterPayload("button_selected.png", "XingShu.button_selected.png", "");
            RegisterPayload("card_base.png", "XingShu.card_base.png", "");
            RegisterPayload("card_feature_header.png", "XingShu.card_feature_header.png", "");
            RegisterPayload("close_hover.png", "XingShu.close_hover.png", "");
            RegisterPayload("close_normal.png", "XingShu.close_normal.png", "");
            RegisterPayload("divider.png", "XingShu.divider.png", "");
            RegisterPayload("floating_entry_active.png", "XingShu.floating_entry_active.png", "");
            RegisterPayload("floating_entry_hover.png", "XingShu.floating_entry_hover.png", "");
            RegisterPayload("floating_entry_idle.png", "XingShu.floating_entry_idle.png", "");
            RegisterPayload("floating_entry_notify.png", "XingShu.floating_entry_notify.png", "");
            RegisterPayload("header_bar.png", "XingShu.header_bar.png", "");
            RegisterPayload("hotkey_badge.png", "XingShu.hotkey_badge.png", "");
            RegisterPayload("sidebar_tab_hover.png", "XingShu.sidebar_tab_hover.png", "");
            RegisterPayload("sidebar_tab_normal.png", "XingShu.sidebar_tab_normal.png", "");
            RegisterPayload("sidebar_tab_selected.png", "XingShu.sidebar_tab_selected.png", "");
            RegisterPayload("slider_fill.png", "XingShu.slider_fill.png", "");
            RegisterPayload("slider_handle.png", "XingShu.slider_handle.png", "");
            RegisterPayload("slider_track.png", "XingShu.slider_track.png", "");
            RegisterPayload("toggle_thumb.png", "XingShu.toggle_thumb.png", "");
            RegisterPayload("toggle_track_off.png", "XingShu.toggle_track_off.png", "");
            RegisterPayload("toggle_track_on.png", "XingShu.toggle_track_on.png", "");
            RegisterPayload("window_frame.png", "XingShu.window_frame.png", "");
        }

        private static void RegisterPayload(string logicalName, string resourceName, string hex)
        {
            byte[] bytes = HexToBytes(hex);
            _payloads[logicalName] = bytes;
            _payloads[resourceName] = bytes;
            if (logicalName.EndsWith(".png", StringComparison.OrdinalIgnoreCase))
            {
                _payloads[logicalName.Substring(0, logicalName.Length - 4)] = bytes;
            }
        }

        internal static byte[] GetPayload(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            byte[] bytes;
            if (_payloads.TryGetValue(key, out bytes))
            {
                return bytes;
            }
            return null;
        }

        internal static int Count => _payloads.Count;

        private static byte[] HexToBytes(string hex)
        {
            int len = hex.Length;
            byte[] bytes = new byte[len / 2];
            for (int i = 0; i < len; i += 2)
            {
                bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
            }
            return bytes;
        }
    }
}
